INSERT OR IGNORE INTO ar_ling_root_asl (id, root_norm, root_id, statement_ar, statement_en, authority_ar, authority_en, death_hijri, source_slug, lexicon_entry_id, page_ref, volume_no, block_id, is_primary, narrows_id, note_md, confidence, status) VALUES ('ASL:دهر:fayyumi_misbah_munir', 'دهر', '2b7c85dbac0ac7c959b000cfde', 'الدَّهْرُ يُطْلَقُ عَلَى الْأَبَدِ وَقِيلَ هُوَ الزَّمَانُ قَلَّ أَوْ كَثُرَ', 'forever; or time, short or long', 'الفيومي', 'al-Fayyūmī, al-Miṣbāḥ al-Munīr', 770, 'fayyumi_misbah_munir', 're_msb_2acbd69e5c165c64', '1009', NULL, 'blk_msb_9d71f6b395e4ec2c', 0, NULL, 'Marker: head gloss. Reading: time, forever.', 'high', 'active');
