INSERT OR IGNORE INTO ar_ling_root_asl (id, root_norm, root_id, statement_ar, statement_en, authority_ar, authority_en, death_hijri, source_slug, lexicon_entry_id, page_ref, volume_no, block_id, is_primary, narrows_id, note_md, confidence, status) VALUES ('ASL:دهر:zabidi_taj_arus', 'دهر', '2b7c85dbac0ac7c959b000cfde', 'الدَّهْرُ فِي الأَصْل اسمٌ لمُدَّة العَالَمِ من ابتاءِ وُجُوده إِلى إِنقضائه', 'the whole span of the world''s time', 'الزبيدي', 'al-Zabīdī, Tāj al-ʿArūs', 1205, 'zabidi_taj_arus', 're_taj_07818eafb9000fd6', '347', 11, 'blk_taj_9d15ab7428bdb0b5', 0, NULL, 'Marker: «في الأصل» (quoting al-Rāghib). Reading: whole span of time. Quoted from al-Rāghib via Tāj.', 'medium', 'active');
